document.addEventListener('DOMContentLoaded', function () {
  const form = document.getElementById('booking-form');
  const list = document.getElementById('booking-list');
  const empty = document.getElementById('empty-state');
  const confirmation = document.querySelector('[data-testid="booking-confirmation"]');
  const count = document.getElementById('booking-count');
  const nameInput = document.querySelector('[data-testid="booking-name"]');
  const emailInput = document.querySelector('[data-testid="booking-email"]');
  const dateInput = document.querySelector('[data-testid="booking-date"]');
  const timeInput = document.querySelector('[data-testid="booking-time"]');
  const typeInput = document.querySelector('[data-testid="booking-type"]');
  const today = new Date();
  today.setMinutes(today.getMinutes() - today.getTimezoneOffset());
  dateInput.min = today.toISOString().slice(0, 10);
  const bookings = [];

  function formatDate(value) { return new Date(value + 'T00:00:00').toLocaleDateString(undefined, { month: 'short', day: 'numeric', year: 'numeric' }); }
  function formatTime(value) { const parts = value.split(':'); const date = new Date(); date.setHours(parts[0], parts[1]); return date.toLocaleTimeString(undefined, { hour: 'numeric', minute: '2-digit' }); }
  function render() {
    empty.hidden = bookings.length > 0;
    list.querySelectorAll('[data-testid="booking"]').forEach(function (element) { element.remove(); });
    bookings.forEach(function (item) {
      const card = document.createElement('article');
      card.className = 'booking-card' + (item.cancelled ? ' cancelled' : '');
      card.dataset.testid = 'booking'; card.dataset.status = item.cancelled ? 'cancelled' : 'active';
      const person = document.createElement('div'); person.className = 'booking-person'; person.dataset.testid = 'booking-name-display'; person.textContent = item.name;
      const type = document.createElement('div'); type.className = 'booking-type'; type.textContent = item.type;
      const meta = document.createElement('div'); meta.className = 'booking-meta'; meta.textContent = formatDate(item.date) + ' · ' + formatTime(item.time) + '\n' + item.email;
      card.append(person, type, meta);
      if (item.cancelled) { const label = document.createElement('span'); label.className = 'cancelled-label'; label.textContent = 'Cancelled'; card.appendChild(label); }
      else { const button = document.createElement('button'); button.className = 'cancel-button'; button.dataset.testid = 'booking-cancel'; button.type = 'button'; button.textContent = 'Cancel'; button.addEventListener('click', function () { item.cancelled = true; render(); }); card.appendChild(button); }
      list.appendChild(card);
    });
    count.textContent = bookings.filter(function (item) { return !item.cancelled; }).length;
  }
  form.addEventListener('submit', function (event) {
    event.preventDefault();
    if (!form.checkValidity()) { form.reportValidity(); return; }
    if (dateInput.value < dateInput.min) { dateInput.setCustomValidity('Please choose today or a future date.'); form.reportValidity(); dateInput.setCustomValidity(''); return; }
    const booking = { name: nameInput.value, email: emailInput.value, date: dateInput.value, time: timeInput.value, type: typeInput.value, cancelled: false };
    bookings.push(booking); render(); confirmation.textContent = 'Appointment confirmed — we look forward to seeing you, ' + booking.name + '!'; confirmation.hidden = false; form.reset(); dateInput.min = today.toISOString().slice(0, 10);
  });
  render();
});
